package cn.binbin.crm;

import java.util.*;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;

public final class P4Defaults {
 private P4Defaults(){}
 private static Map<String,Object> p(Object... values){return SaasService.parameters(values);}
 public static void initialize(NamedParameterJdbcTemplate db,UUID tenant,String name){db.queryForObject("SELECT set_config('crm.tenant_id',:tenant,true)",Map.of("tenant",tenant.toString()),String.class);db.update("INSERT INTO sys_tenant_profile(tenant_id,brand_name) VALUES(:tenant,:name) ON CONFLICT DO NOTHING",p("tenant",tenant,"name",name));String[][] stages={{"OPPORTUNITY","CONTACT","初步接触","10","10","false"},{"OPPORTUNITY","NEEDS","需求确认","20","25","false"},{"OPPORTUNITY","SOLUTION","方案报价","30","50","false"},{"OPPORTUNITY","NEGOTIATION","商务谈判","40","70","false"},{"OPPORTUNITY","READY","待签约","50","90","false"},{"OPPORTUNITY","WON","成交","60","100","true"},{"OPPORTUNITY","LOST","丢单","70","0","true"},{"TICKET","NEW","新建","10","0","false"},{"TICKET","IN_PROGRESS","处理中","20","0","false"},{"TICKET","WAITING_CUSTOMER","等待客户","30","0","false"},{"TICKET","RESOLVED","已解决","40","0","false"},{"TICKET","CLOSED","已关闭","50","0","true"},{"TICKET","CANCELLED","已取消","60","0","true"}};for(var s:stages)db.update("INSERT INTO crm_process_stage(id,tenant_id,process_type,stage_code,label,position,probability,terminal) VALUES(:id,:tenant,:type,:code,:label,:position,:probability,:terminal) ON CONFLICT DO NOTHING",p("id",UUID.randomUUID(),"tenant",tenant,"type",s[0],"code",s[1],"label",s[2],"position",Integer.parseInt(s[3]),"probability",Integer.parseInt(s[4]),"terminal",Boolean.parseBoolean(s[5])));String[][] numbers={{"QUOTE","QT"},{"CONTRACT","CT"},{"RECEIPT","RC"},{"REVERSAL","RV"},{"TICKET","CS"}};for(var n:numbers)db.update("INSERT INTO crm_number_rule(id,tenant_id,document_type,prefix) VALUES(:id,:tenant,:type,:prefix) ON CONFLICT DO NOTHING",p("id",UUID.randomUUID(),"tenant",tenant,"type",n[0],"prefix",n[1]));db.update("INSERT INTO crm_approval_rule(id,tenant_id,process_type,name) VALUES(:id,:tenant,'QUOTE','报价一级审批') ON CONFLICT DO NOTHING",p("id",UUID.randomUUID(),"tenant",tenant));String[][] types={{"GENERAL","一般咨询"},{"QUALITY","质量问题"},{"DELIVERY","交付问题"},{"TECHNICAL","技术支持"}};int pos=10;for(var t:types){db.update("INSERT INTO crm_dictionary_item(id,tenant_id,dictionary_type,item_code,label,position) VALUES(:id,:tenant,'TICKET_TYPE',:code,:label,:position) ON CONFLICT DO NOTHING",p("id",UUID.randomUUID(),"tenant",tenant,"code",t[0],"label",t[1],"position",pos));pos+=10;}}
}
